using Microsoft.UI.Windowing;using Microsoft.UI.Xaml;using Microsoft.UI.Xaml.Controls;using Timarker.Models;using Timarker_WinUI.Services;namespace Timarker_WinUI;public sealed class FloatingNoteWindow:Window{private readonly NoteItem _note;private readonly TextBox _text;public FloatingNoteWindow(NoteItem note){_note=note;Title=note.Title;AppWindow.Resize(new Windows.Graphics.SizeInt32(360,280));AppWindow.SetPresenter(AppWindowPresenterKind.Overlapped);if(AppWindow.Presenter is OverlappedPresenter p)p.IsAlwaysOnTop=true;var root=new Grid{Padding=new Thickness(16)};root.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});root.RowDefinitions.Add(new RowDefinition());var title=new TextBox{Text=note.Title,FontSize=18,FontWeight=Microsoft.UI.Text.FontWeights.SemiBold};_text=new TextBox{Text=note.Content,AcceptsReturn=true,TextWrapping=TextWrapping.Wrap,VerticalContentAlignment=VerticalAlignment.Top,Margin=new Thickness(0,10,0,0)};Grid.SetRow(_text,1);root.Children.Add(title);root.Children.Add(_text);Content=root;Closed+=(s,e)=>{_note.Title=string.IsNullOrWhiteSpace(title.Text)?"无标题便签":title.Text.Trim();_note.Content=_text.Text;_note.UpdatedAt=DateTime.Now;AppData.Current.Save();};}}
